package com.ias.ticket;

import com.ias.trust.*;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.web.bind.annotation.*;
import java.math.BigDecimal;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;

@RestController
public class Completion {
 final Tickets t;final StaffAccess access;
 public Completion(Tickets t,StaffAccess access){this.t=t;this.access=access;}
 static Problem conflict(String code){return new Problem(409,code);}
 static Instant instant(Object v){return Instant.parse(Tickets.utc(v));}
 BigDecimal hours(Map<String,Object> row){return t.db.queryForObject("SELECT COALESCE(SUM(work_hours),0) FROM ticket_processing_record WHERE ticket_id=? AND round_id=? AND type='RECORDS'",BigDecimal.class,row.get("id"),row.get("round_id")).setScale(2);}
 Instant now(){return t.db.queryForObject("SELECT UTC_TIMESTAMP(3)",(rs,n)->rs.getTimestamp(1).toInstant());}
 Map<String,Object> fields(String action,Map<String,Object> b){
  Set<String> required=switch(action){case "solve"->Set.of("expectedVersion","roundId","assignmentId","cause","resolutionMethod","completedAt","confirmedWorkHours","customerMessage","evidenceFileIds");case "customer-decision"->Set.of("expectedVersion","roundId","decision");case "close"->Set.of("expectedVersion","roundId","solutionId","closeMessage","acknowledged");default->throw Tickets.bad();};
  var allowed=new HashSet<>(required);if(action.equals("customer-decision")&&"RETURN".equals(b.get("decision")))allowed.add("reason");
  if(!allowed.containsAll(b.keySet())||!b.keySet().containsAll(required))throw Tickets.bad();var data=new TreeMap<String,Object>(b);
  if(!(data.get("expectedVersion") instanceof String))throw Tickets.bad();data.put("expectedVersion",Long.toString(Tickets.id(data.get("expectedVersion"))));Tickets.uuid(data.get("roundId"));
  if(action.equals("solve")){
   Tickets.uuid(data.get("assignmentId"));for(String key:List.of("cause","resolutionMethod","customerMessage"))Tickets.text(data.get(key),5,2000,true);
   try{if(!(data.get("completedAt") instanceof String date)||!date.matches(".*(?:Z|[+-][0-9]{2}:[0-9]{2})$"))throw Tickets.bad();Instant value=OffsetDateTime.parse(date).toInstant();if(!value.equals(value.truncatedTo(java.time.temporal.ChronoUnit.MILLIS)))throw Tickets.bad();data.put("completedAt",value.toString());}catch(Exception e){throw Tickets.bad();}
   if(!(data.get("confirmedWorkHours") instanceof String h)||!h.matches("(?:0|[1-9][0-9]{0,9})(?:\\.[0-9]{1,2})?"))throw Tickets.bad();data.put("confirmedWorkHours",new BigDecimal(h).setScale(2).toPlainString());
   if(!(data.get("evidenceFileIds") instanceof List<?> list)||list.size()>5)throw new Problem(400,"INVALID_SOLUTION_EVIDENCE");List<String> ids;try{ids=list.stream().map(Tickets::uuid).sorted().toList();}catch(Problem e){throw new Problem(400,"INVALID_SOLUTION_EVIDENCE");}if(new HashSet<>(ids).size()!=ids.size())throw new Problem(400,"INVALID_SOLUTION_EVIDENCE");data.put("evidenceFileIds",ids);
  }else if(action.equals("customer-decision")){
   if(!(data.get("decision") instanceof String choice)||!Set.of("CONFIRM","RETURN").contains(choice))throw Tickets.bad();if(data.get("decision").equals("RETURN"))Tickets.text(data.get("reason"),5,500,true);
  }else{Tickets.uuid(data.get("solutionId"));Tickets.text(data.get("closeMessage"),5,500,true);if(!Boolean.TRUE.equals(data.get("acknowledged")))throw Tickets.bad();}
  return data;
 }
 Tickets.Actor actor(HttpServletRequest r,String action){Chain.source(r);long deadline=Chain.deadline(r);String purpose=action.equals("customer-decision")?"TICKET_CUSTOMER_DECIDE":"TICKET_WORK";var value=Chain.identity("ticket-identity",Chain.cookie(r),purpose,r.getHeader("X-CSRF-TOKEN"),Chain.trace(r),deadline);Chain.fresh(value,deadline);return new Tickets.Actor(Tickets.id(value.get("tenantId")),Tickets.id(value.get("userId")),value.get("identityType").toString(),Chain.cookie(r),r.getHeader("X-CSRF-TOKEN"),Chain.trace(r),deadline,value.get("attempt").toString());}
 @PostMapping("/api/ticket/tickets/{key}/solutions") Map<String,Object> solve(@PathVariable String key,@RequestBody Map<String,Object>b,HttpServletRequest r){Instant received=Instant.now();return perform(key,"solve",fields("solve",b),actor(r,"solve"),Tickets.uuid(Chain.single(r,"Idempotency-Key")),received);}
 @PostMapping("/api/ticket/tickets/{key}/solutions/{solution}/decision") Map<String,Object> decide(@PathVariable String key,@PathVariable String solution,@RequestBody Map<String,Object>b,HttpServletRequest r){var data=fields("customer-decision",b);data.put("solutionId",Tickets.uuid(solution));return perform(key,"customer-decision",data,actor(r,"customer-decision"),Tickets.uuid(Chain.single(r,"Idempotency-Key")),Instant.now());}
 @PostMapping("/api/ticket/tickets/{key}/close") Map<String,Object> close(@PathVariable String key,@RequestBody Map<String,Object>b,HttpServletRequest r){return perform(key,"close",fields("close",b),actor(r,"close"),Tickets.uuid(Chain.single(r,"Idempotency-Key")),Instant.now());}
 Map<String,Object> perform(String key,String action,Map<String,Object>b,Tickets.Actor a,String operation,Instant received){
  Tickets.uuid(key);t.accessible(key,a);String digest=Tickets.hash(b);
  return t.tx.execute(tx->{
   t.lockActor(a.tenant(),a.user());var row=t.db.queryForMap("SELECT * FROM ticket_record WHERE id=? AND tenant_id=? FOR UPDATE",key,a.tenant());
   String purpose=action.equals("customer-decision")?"TICKET_CUSTOMER_DECIDE":"TICKET_WORK";Chain.fresh(Chain.identity("ticket-identity",a.token(),purpose,a.csrf(),a.trace(),a.deadline()),a.deadline());
   Map<String,Object> facts=null;
   if(action.equals("customer-decision")){if(!a.type().equals("CUSTOMER")||Tickets.id(row.get("reporter_user_id"))!=a.user())throw new Problem(404,"TARGET_NOT_ACCESSIBLE");t.accessible(key,a);}
   else{facts=access.facts(a);if(action.equals("solve")){if(!access.engineer(facts,row))throw new Problem(404,"TARGET_NOT_ACCESSIBLE");if(!access.permission(facts,"ticket.solution.submit")||!access.permission(facts,"ticket.record"))throw new Problem(403,"ACCESS_DENIED");}else access.customerService(facts,row,"ticket.close");}
   var previous=t.db.queryForList("SELECT * FROM ticket_action_operation WHERE operation_id=? FOR UPDATE",operation);
   if(!previous.isEmpty()){var old=previous.getFirst();if(Tickets.id(old.get("tenant_id"))!=a.tenant()||Tickets.id(old.get("actor_user_id"))!=a.user()||!old.get("ticket_id").equals(key))throw new Problem(404,"OPERATION_NOT_FOUND");if(!action.equals(old.get("action"))||!digest.equals(old.get("request_digest")))throw conflict("IDEMPOTENCY_CONFLICT");return Tickets.json(old.get("result_json"));}
   StockExecutionBoundary.guard(t,key);if(!row.get("round_id").equals(b.get("roundId")))throw conflict("ROUND_CONFLICT");long version=Tickets.id(row.get("row_version"));if(version==Long.MAX_VALUE||version!=Tickets.id(b.get("expectedVersion")))throw conflict("VERSION_CONFLICT");
   if(row.get("assignment_id")!=null)t.db.queryForList("SELECT id FROM ticket_assignment WHERE id=? FOR UPDATE",row.get("assignment_id"));
   Map<String,Object> solution=current(row,true);Instant time=now();String next,body,solutionId,record=UUID.randomUUID().toString(),nextAction;var extra=new LinkedHashMap<String,Object>();
   if(action.equals("solve")){
    Workflow.state(row.get("status").toString(),"IN_PROGRESS");if(!Objects.equals(row.get("assignment_id"),b.get("assignmentId")))throw conflict("ASSIGNMENT_CONFLICT");requireSupported(row,a);
    if(solution!=null&&decision(solution.get("id"),true)==null)throw conflict("SOLUTION_CONFLICT");
    Instant completed=Instant.parse(b.get("completedAt").toString());if(completed.isBefore(Rounds.start(row))||completed.isAfter(received)||completed.isAfter(time))throw Tickets.bad();
    BigDecimal total=hours(row);if(total.compareTo(new BigDecimal(b.get("confirmedWorkHours").toString()))!=0)throw new Problem(400,"WORK_HOURS_MISMATCH");if(total.precision()>12)throw Tickets.bad();validateEvidence(key,(List<?>)b.get("evidenceFileIds"));
    int attempt=t.db.queryForObject("SELECT COALESCE(MAX(attempt_no),0)+1 FROM ticket_solution WHERE ticket_id=? AND round_id=?",Integer.class,key,b.get("roundId"));solutionId=UUID.randomUUID().toString();
    new Transfers(t,access).terminate(row,a,operation,"SOLUTION_SUBMITTED",time);t.db.update("INSERT INTO ticket_solution(id,ticket_id,round_id,assignment_id,attempt_no,operation_id,engineer_user_id,cause,resolution_method,customer_message,completed_at,submitted_at,confirmed_work_hours,evidence_file_ids) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)",solutionId,key,b.get("roundId"),b.get("assignmentId"),attempt,operation,a.user(),b.get("cause"),b.get("resolutionMethod"),b.get("customerMessage"),Timestamp.from(completed),Timestamp.from(time),total,Chain.JSON.writeValueAsString(b.get("evidenceFileIds")));
    t.db.update("UPDATE ticket_record SET current_solution_id=? WHERE id=?",solutionId,key);next="PENDING_CUSTOMER_CONFIRMATION";body="工程师已提交解决方案，请原报修人确认。";nextAction="WAIT_CUSTOMER_DECISION";extra.put("attemptNo",attempt);extra.put("submittedAt",time.toString());
   }else if(action.equals("customer-decision")){
    if(solution==null||!Objects.equals(solution.get("id"),b.get("solutionId")))throw conflict("SOLUTION_CONFLICT");Workflow.state(row.get("status").toString(),"PENDING_CUSTOMER_CONFIRMATION");if(decision(solution.get("id"),true)!=null)throw conflict("INVALID_STATE");
    solutionId=solution.get("id").toString();var dual=calculateDual(row,time);var timing=dual.confirmation();String choice=b.get("decision").toString();
    t.db.update("INSERT INTO ticket_solution_decision(solution_id,ticket_id,round_id,operation_id,actor_user_id,decision,reason,decided_at,effective_resolution_ms,excluded_confirmation_ms,excluded_supplement_ms) VALUES(?,?,?,?,?,?,?,?,?,?,?)",solutionId,key,b.get("roundId"),operation,a.user(),choice,b.get("reason"),Timestamp.from(time),timing.effectiveMs(),timing.excludedMs(),dual.excludedSupplementMs());
    if(choice.equals("CONFIRM"))new Cancellations(t,access).confirmed(row,a,operation,time);next=choice.equals("CONFIRM")?"RESOLVED":"IN_PROGRESS";body=choice.equals("CONFIRM")?"原报修人已确认问题解决。":"原报修人反馈未解决："+b.get("reason");nextAction=choice.equals("CONFIRM")?"WAIT_STAFF_CLOSE":"CONTINUE_PROCESSING";extra.put("decision",choice);extra.put("decidedAt",time.toString());
   }else{
    if(solution==null||!Objects.equals(solution.get("id"),b.get("solutionId")))throw conflict("SOLUTION_CONFLICT");var check=check(row,a);if(!Boolean.TRUE.equals(check.get("canClose")))throw conflict(((List<String>)check.get("blockers")).getFirst());
    solutionId=solution.get("id").toString();t.db.update("INSERT INTO ticket_closure(ticket_id,round_id,solution_id,operation_id,closed_by,closed_at,close_message,check_json) VALUES(?,?,?,?,?,?,?,?)",key,b.get("roundId"),solutionId,operation,a.user(),Timestamp.from(time),b.get("closeMessage"),Chain.JSON.writeValueAsString(check));next="CLOSED";body=b.get("closeMessage").toString();nextAction="VIEW_TICKET";extra.put("closedAt",time.toString());extra.put("closeCheck",check);
   }
   if(action.equals("solve"))new Rounds(t).first(row,a,record,time,operation);
   var qualification=facts==null?Map.of("identityType","CUSTOMER"):new Workflow(t,access).qualification(facts);
   t.db.update("INSERT INTO ticket_processing_record(id,ticket_id,round_id,assignment_id,operation_id,actor_user_id,type,body,work_hours,visibility,qualification_json,row_version,occurred_at) VALUES(?,?,?,?,?,?,?,?,0,'CUSTOMER_VISIBLE',?,?,?)",record,key,b.get("roundId"),row.get("assignment_id"),operation,a.user(),action.replace('-','_').toUpperCase(Locale.ROOT),body,Chain.JSON.writeValueAsString(qualification),version+1,Timestamp.from(time));
   t.db.update("UPDATE ticket_record SET status=?,row_version=row_version+1 WHERE id=?",next,key);
   if(action.equals("solve")&&row.get("reporter_user_id")!=null){
    var occurred=time.truncatedTo(java.time.temporal.ChronoUnit.MILLIS);
    var payload=new TreeMap<String,String>();payload.put("ticketId",key);payload.put("roundId",b.get("roundId").toString());payload.put("companyId",row.get("company_id").toString());payload.put("stateCode",next);payload.put("action","SOLVE");payload.put("processingRecordId",record);payload.put("solutionId",solutionId);
    var envelope=new LinkedHashMap<String,Object>();envelope.put("eventId",operation);envelope.put("type","ticket.resolution_submitted");envelope.put("schemaVersion",1);envelope.put("tenantId",Long.toString(a.tenant()));envelope.put("aggregateId",key);envelope.put("aggregateVersion",Long.toString(version+1));envelope.put("occurredAt",String.format(java.util.Locale.ROOT,"%s.%03dZ",occurred.toString().substring(0,19),occurred.getNano()/1_000_000));envelope.put("producer","ticket");envelope.put("correlationId",operation);envelope.put("payload",payload);
    String json=Chain.JSON.writeValueAsString(envelope),eventDigest=Tickets.hash(json);
    t.db.update("INSERT INTO ticket_customer_notification_outbox(event_id,tenant_id,event_type,aggregate_id,aggregate_version,ticket_id,round_id,company_id,recipient_user_id,state_code,envelope,event_digest,delivery_state,attempt_count,next_attempt_at,created_at) VALUES(?,?,'ticket.resolution_submitted',?,?,?,?,?,?,?,?,?,'PENDING',0,?,?)",operation,a.tenant(),key,version+1,key,b.get("roundId"),row.get("company_id"),row.get("reporter_user_id"),next,json,eventDigest,Timestamp.from(occurred),Timestamp.from(occurred));
   }
   if(action.equals("close")&&row.get("reporter_user_id")!=null){
    var occurred=time.truncatedTo(java.time.temporal.ChronoUnit.MILLIS);
    var payload=new TreeMap<String,String>();payload.put("ticketId",key);payload.put("roundId",b.get("roundId").toString());payload.put("companyId",row.get("company_id").toString());payload.put("stateCode",next);payload.put("action","CLOSE");payload.put("processingRecordId",record);payload.put("solutionId",solutionId);
    var envelope=new LinkedHashMap<String,Object>();envelope.put("eventId",operation);envelope.put("type","ticket.closed");envelope.put("schemaVersion",1);envelope.put("tenantId",Long.toString(a.tenant()));envelope.put("aggregateId",key);envelope.put("aggregateVersion",Long.toString(version+1));envelope.put("occurredAt",String.format(java.util.Locale.ROOT,"%s.%03dZ",occurred.toString().substring(0,19),occurred.getNano()/1_000_000));envelope.put("producer","ticket");envelope.put("correlationId",operation);envelope.put("payload",payload);
    String json=Chain.JSON.writeValueAsString(envelope),eventDigest=Tickets.hash(json);
    t.db.update("INSERT INTO ticket_customer_notification_outbox(event_id,tenant_id,event_type,aggregate_id,aggregate_version,ticket_id,round_id,company_id,recipient_user_id,state_code,envelope,event_digest,delivery_state,attempt_count,next_attempt_at,created_at) VALUES(?,?,'ticket.closed',?,?,?,?,?,?,?,?,?,'PENDING',0,?,?)",operation,a.tenant(),key,version+1,key,b.get("roundId"),row.get("company_id"),row.get("reporter_user_id"),next,json,eventDigest,Timestamp.from(occurred),Timestamp.from(occurred));
   }
   var result=new LinkedHashMap<String,Object>();result.putAll(Map.of("operationId",operation,"action",action,"state","COMPLETED","ticketId",key,"solutionId",solutionId,"roundId",b.get("roundId"),"status",next,"rowVersion",Long.toString(version+1),"recordId",record,"nextAction",nextAction));result.put("assignmentId",row.get("assignment_id"));result.putAll(extra);
   t.db.update("INSERT INTO ticket_action_operation(operation_id,tenant_id,actor_user_id,ticket_id,action,request_digest,result_json,created_at) VALUES(?,?,?,?,?,?,?,?)",operation,a.tenant(),a.user(),key,action,digest,Chain.JSON.writeValueAsString(result),Timestamp.from(time));
   t.db.update("INSERT INTO ticket_audit(operation_id,tenant_id,actor_user_id,action,occurred_at) VALUES(?,?,?,?,?)",operation,a.tenant(),a.user(),"WORKFLOW_"+action.replace('-','_').toUpperCase(Locale.ROOT),Timestamp.from(time));if(action.equals("close"))new Rounds(t).freeze(t.db.queryForMap("SELECT * FROM ticket_record WHERE id=?",key),time);Chain.remaining(a.deadline());return result;
  });
 }
 Map<String,Object> current(Map<String,Object> row,boolean lock){if(row.get("current_solution_id")==null)return null;var rows=t.db.queryForList("SELECT * FROM ticket_solution WHERE id=? AND ticket_id=? AND round_id=?"+(lock?" FOR UPDATE":""),row.get("current_solution_id"),row.get("id"),row.get("round_id"));if(rows.isEmpty())throw conflict("COMPLETION_DATA_INVALID");return rows.getFirst();}
 Map<String,Object> decision(Object solution,boolean lock){var rows=t.db.queryForList("SELECT * FROM ticket_solution_decision WHERE solution_id=?"+(lock?" FOR UPDATE":""),solution);return rows.isEmpty()?null:rows.getFirst();}
 static boolean supported(Map<String,Object>row,String mode){return "DISABLED".equals(mode)&&"ORDINARY_REPAIR_V1".equals(row.get("completion_scope"))&&row.get("related_business_json")==null;}
 boolean supported(Map<String,Object>row){return supported(row,System.getenv().getOrDefault("IAS_TICKET_EXTERNAL_WORKFLOWS","DISABLED"));}
 void requireSupported(Map<String,Object>row){if(!supported(row))throw conflict("UNSUPPORTED_RELATED_BUSINESS");new ApprovalBoundary(t,access).requireCompletionClear(row.get("id").toString());}
 void requireSupported(Map<String,Object>row,Tickets.Actor actor){if(!supported(row))throw conflict("UNSUPPORTED_RELATED_BUSINESS");if(!new CompletionPartsProof(t,CompletionPartsProof.trusted(actor)).clear(row))throw conflict("RELATED_APPROVAL_OR_PARTS_PENDING");}
 void validateEvidence(String key,List<?> ids){for(Object id:ids)if(t.db.queryForObject("SELECT COUNT(*) FROM ticket_file_reference x JOIN ticket_file f ON f.id=x.file_id WHERE x.ticket_id=? AND x.file_id=? AND f.state='READY'",Long.class,key,id)!=1)throw new Problem(400,"INVALID_SOLUTION_EVIDENCE");}
 Map<String,Object> check(Map<String,Object> row,Tickets.Actor actor){
  var solution=current(row,false);var decided=solution==null?null:decision(solution.get("id"),false);boolean confirmed=decided!=null&&"CONFIRM".equals(decided.get("decision"));boolean complete=solution!=null&&Objects.equals(solution.get("assignment_id"),row.get("assignment_id"))&&confirmed&&new BigDecimal(solution.get("confirmed_work_hours").toString()).compareTo(hours(row))==0;
  if(complete)try{for(String key:List.of("cause","resolution_method","customer_message"))Tickets.text(solution.get(key),5,2000,true);validateEvidence(row.get("id").toString(),Chain.JSON.readValue(solution.get("evidence_file_ids").toString(),List.class));if(instant(solution.get("completed_at")).isBefore(Rounds.start(row))||instant(solution.get("completed_at")).isAfter(instant(solution.get("submitted_at")))||instant(decided.get("decided_at")).isBefore(instant(solution.get("submitted_at"))))complete=false;}catch(Problem e){complete=false;}
  var blockers=new ArrayList<String>();if(!supported(row))blockers.add("UNSUPPORTED_RELATED_BUSINESS");if(!"RESOLVED".equals(row.get("status"))||!confirmed)blockers.add("CUSTOMER_CONFIRMATION_REQUIRED");if(!complete)blockers.add("COMPLETION_DATA_INVALID");
  var result=new LinkedHashMap<String,Object>();result.put("ticketId",row.get("id"));result.put("roundId",row.get("round_id"));result.put("solutionId",row.get("current_solution_id"));result.put("rowVersion",row.get("row_version").toString());result.put("customerConfirmed",confirmed);result.put("materialsComplete",complete);result.put("scope","ORDINARY_REPAIR_ONLY");result.put("relatedWorkflows",supported(row)?"NOT_ENABLED":"UNSUPPORTED");result.put("canClose",blockers.isEmpty());result.put("blockers",blockers);
  boolean clear;try{StockExecutionBoundary.guard(t,row.get("id").toString());clear=new CompletionPartsProof(t,CompletionPartsProof.trusted(actor)).clear(row);}catch(Problem e){if(e.status!=409)throw e;clear=false;}
  if(!clear){blockers.add("RELATED_APPROVAL_OR_PARTS_PENDING");result.put("relatedWorkflows","APPROVAL_OR_PARTS_PENDING");result.put("externalOwnerCleanupVerified",false);result.put("canClose",false);}
  else if(new ApprovalBoundary(t,access).blocking(row.get("id").toString())>0){result.put("relatedWorkflows","APPROVAL_AND_PARTS_CLEARED");result.put("externalOwnerCleanupVerified",true);}
  return result;
 }
 @GetMapping("/api/ticket/tickets/{key}/close-check") Map<String,Object> check(@PathVariable String key,HttpServletRequest r){if(!r.getParameterMap().isEmpty())throw Tickets.bad();var a=t.actor(r,false);if(!a.type().equals("EMPLOYEE"))throw new Problem(403,"ACCESS_DENIED");var row=t.accessible(key,a);access.customerService(access.facts(a),row,"ticket.close");return check(row,a);}
 Map<String,Object> view(Map<String,Object> solution){var out=new LinkedHashMap<String,Object>();for(String[] pair:new String[][]{{"solutionId","id"},{"roundId","round_id"},{"assignmentId","assignment_id"},{"attemptNo","attempt_no"},{"cause","cause"},{"resolutionMethod","resolution_method"},{"customerMessage","customer_message"}})out.put(pair[0],solution.get(pair[1]));out.put("engineerUserId",solution.get("engineer_user_id").toString());out.put("submittedAt",Tickets.utc(solution.get("submitted_at")));out.put("completedAt",Tickets.utc(solution.get("completed_at")));out.put("confirmedWorkHours",solution.get("confirmed_work_hours").toString());out.put("evidenceFileIds",Chain.JSON.readValue(solution.get("evidence_file_ids").toString(),List.class));var decided=decision(solution.get("id"),false);if(decided==null)out.put("decision",null);else{var d=new LinkedHashMap<String,Object>();d.put("decision",decided.get("decision"));d.put("reason",decided.get("reason"));d.put("actorUserId",decided.get("actor_user_id").toString());d.put("decidedAt",Tickets.utc(decided.get("decided_at")));out.put("decision",d);}var termination=t.db.queryForList("SELECT cancelled_at FROM ticket_cancellation WHERE terminated_solution_id=?",solution.get("id"));out.put("termination",termination.isEmpty()?null:Map.of("reason","CANCELLED","terminatedAt",Tickets.utc(termination.getFirst().get("cancelled_at"))));return out;}
 @GetMapping("/api/ticket/tickets/{key}/solutions") Map<String,Object> history(@PathVariable String key,HttpServletRequest r){var a=t.actor(r,false);var visible=t.accessible(key,a);String selectedRound=new Rounds(t).selected(r,visible);for(var e:r.getParameterMap().entrySet())if(!Set.of("page","size","roundId").contains(e.getKey())||e.getValue().length!=1)throw Tickets.bad();long page=r.getParameter("page")==null?1:Tickets.id(r.getParameter("page")),size=r.getParameter("size")==null?20:Tickets.id(r.getParameter("size"));if(page>1000000||!Set.of(20L,50L,100L).contains(size))throw Tickets.bad();return Map.of("items",t.db.queryForList("SELECT * FROM ticket_solution WHERE ticket_id=? AND round_id=? ORDER BY submitted_at DESC,attempt_no DESC,id DESC LIMIT ? OFFSET ?",key,selectedRound,size,(page-1)*size).stream().map(this::view).toList(),"total",t.db.queryForObject("SELECT COUNT(*) FROM ticket_solution WHERE ticket_id=? AND round_id=?",Long.class,key,selectedRound),"page",page,"size",size);}
 CompletionTiming.Result calculate(Map<String,Object>row,Instant time){var intervals=t.db.queryForList("SELECT s.submitted_at,d.decided_at FROM ticket_solution s LEFT JOIN ticket_solution_decision d ON d.solution_id=s.id WHERE s.ticket_id=? AND s.round_id=? ORDER BY s.attempt_no",row.get("id"),row.get("round_id")).stream().map(s->new CompletionTiming.Interval(instant(s.get("submitted_at")),s.get("decided_at")==null?null:instant(s.get("decided_at")))).toList();return CompletionTiming.calculate(Rounds.start(row),time,intervals,"PENDING_CUSTOMER_CONFIRMATION".equals(row.get("status")));}
 CompletionTiming.Dual calculateDual(Map<String,Object>row,Instant time){var confirm=t.db.queryForList("SELECT s.submitted_at,d.decided_at FROM ticket_solution s LEFT JOIN ticket_solution_decision d ON d.solution_id=s.id WHERE s.ticket_id=? AND s.round_id=? ORDER BY s.attempt_no",row.get("id"),row.get("round_id")).stream().map(r->new CompletionTiming.Interval(instant(r.get("submitted_at")),r.get("decided_at")==null?null:instant(r.get("decided_at")))).toList();var supplements=t.db.queryForList("SELECT s.requested_at,d.replied_at FROM ticket_supplement_request s LEFT JOIN ticket_supplement_reply d ON d.request_id=s.id WHERE s.ticket_id=? AND s.round_id=? ORDER BY s.requested_at,s.id",row.get("id"),row.get("round_id")).stream().map(r->new CompletionTiming.Interval(instant(r.get("requested_at")),r.get("replied_at")==null?null:instant(r.get("replied_at")))).toList();return CompletionTiming.calculate(Rounds.start(row),time,confirm,supplements,"PENDING_CUSTOMER_CONFIRMATION".equals(row.get("status")),"WAITING_INFORMATION".equals(row.get("status")));}
 Map<String,Object> timing(Map<String,Object>row,Instant time){var cancelled=new Cancellations(t,access).fact(row);if(cancelled!=null)return Tickets.json(cancelled.get("timing_json"));var solution=current(row,false);var decided=solution==null?null:decision(solution.get("id"),false);boolean frozen=decided!=null&&"CONFIRM".equals(decided.get("decision"));if(frozen)time=instant(decided.get("decided_at"));var dual=calculateDual(row,time);var result=dual.confirmation();long effective=frozen?Tickets.idOrZero(decided.get("effective_resolution_ms")):result.effectiveMs(),excluded=frozen?Tickets.idOrZero(decided.get("excluded_confirmation_ms")):result.excludedMs();long target=Duration.between(Rounds.start(row),instant(row.get("resolution_due_at"))).toMillis();var first=t.db.queryForList("SELECT submitted_at FROM ticket_solution WHERE ticket_id=? AND round_id=? ORDER BY attempt_no LIMIT 1",row.get("id"),row.get("round_id"));var out=new LinkedHashMap<String,Object>();out.put("roundStartedAt",Rounds.start(row).toString());out.put("firstSolutionSubmittedAt",first.isEmpty()?null:Tickets.utc(first.getFirst().get("submitted_at")));out.put("firstSubmissionElapsedMs",result.firstMs()==null?null:result.firstMs().toString());out.put("firstSubmissionEffectiveMs",dual.firstEffectiveMs()==null?null:dual.firstEffectiveMs().toString());out.put("firstSubmissionOverdue",dual.firstEffectiveMs()==null?null:dual.firstEffectiveMs()>target);long supplementExcluded=frozen?Tickets.idOrZero(decided.get("excluded_supplement_ms")):dual.excludedSupplementMs();out.put("supplementWaitMs",Long.toString(dual.supplementWaitMs()));out.put("excludedSupplementMs",Long.toString(supplementExcluded));out.put("remainingSupplementDeductionMs",Long.toString(CompletionTiming.LIMIT-supplementExcluded));out.put("supplementDeductionLimitMs",Long.toString(CompletionTiming.LIMIT));out.put("currentSupplementWaitMs",Long.toString(dual.currentSupplementWaitMs()));out.put("currentSupplementWaitOver72Hours",dual.supplementOver72());out.put("confirmationWaitMs",Long.toString(result.waitMs()));out.put("excludedConfirmationMs",Long.toString(excluded));out.put("remainingConfirmationDeductionMs",Long.toString(CompletionTiming.LIMIT-excluded));out.put("effectiveResolutionMs",Long.toString(effective));out.put("confirmationDeductionLimitMs",Long.toString(CompletionTiming.LIMIT));out.put("currentWaitOver72Hours",result.currentOver72());out.put("needsCoordination",dual.needsCoordination());out.put("finalFrozen",frozen);out.put("resolutionTargetMs",Long.toString(target));out.put("finalResolutionOverdue",frozen?effective>target:null);return out;}
 void project(Map<String,Object>out,Map<String,Object>row,Tickets.Actor a){out.put("recordedWorkHours",hours(row).toPlainString());var solution=current(row,false);out.put("currentSolution",solution==null?null:view(solution));var closed=t.db.queryForList("SELECT solution_id,closed_by,closed_at,close_message FROM ticket_closure WHERE ticket_id=? AND round_id=?",row.get("id"),row.get("round_id"));if(closed.isEmpty())out.put("closure",null);else{var c=closed.getFirst();out.put("closure",Map.of("solutionId",c.get("solution_id"),"closedBy",c.get("closed_by").toString(),"closedAt",Tickets.utc(c.get("closed_at")),"closeMessage",c.get("close_message")));}out.put("timing",timing(row,now()));var actions=new ArrayList<String>((List<String>)out.get("allowedActions"));if(a.type().equals("CUSTOMER")){if("PENDING_CUSTOMER_CONFIRMATION".equals(row.get("status"))&&Tickets.id(row.get("reporter_user_id"))==a.user())actions.addAll(List.of("customer-confirm","customer-return"));}else{var f=access.facts(a);if("IN_PROGRESS".equals(row.get("status"))&&access.engineer(f,row)&&access.permission(f,"ticket.record")&&access.permission(f,"ticket.solution.submit"))actions.add("solve");if("RESOLVED".equals(row.get("status"))&&access.company(f,row.get("company_id"))&&access.permission(f,"ticket.close"))actions.add("close");}out.put("allowedActions",actions);}
}

